args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?younger ?youngerLabel ?birthDate WHERE {
  BIND(dbr:Ebtissam_Mohamed AS ?a)
  BIND(dbr:Beekman_Du_Barry AS ?b)

  OPTIONAL { ?a dbo:birthDate ?a_d1. }
  OPTIONAL { ?a dbp:birthDate ?a_d2. }
  OPTIONAL { ?b dbo:birthDate ?b_d1. }
  OPTIONAL { ?b dbp:birthDate ?b_d2. }

  BIND(COALESCE(?a_d1, ?a_d2) AS ?dA)
  BIND(COALESCE(?b_d1, ?b_d2) AS ?dB)

  FILTER(bound(?dA) && bound(?dB))

  {
    FILTER(xsd:date(?dA) > xsd:date(?dB))
    BIND(?a AS ?younger)
    BIND(?dA AS ?birthDate)
  }
  UNION
  {
    FILTER(xsd:date(?dB) > xsd:date(?dA))
    BIND(?b AS ?younger)
    BIND(?dB AS ?birthDate)
  }

  OPTIONAL { ?younger rdfs:label ?youngerLabel . FILTER(lang(?youngerLabel)='en') }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

